-- Popula effects_catalog (aba "Condições e Efeitos") com dados reais do Livro Base v1.3
-- e VTT_Ameacas_Ordem_Paranormal.md, passados pela Millie. Rituais ficam de fora
-- (já 100% catalogados na tabela `rituals`).

insert into effects_catalog (source_id, category, name, description) values

((select id from sources where slug='ordem_paranormal'), 'condicao', 'Abalado', $$Sofre -1d20 em testes. Se ficar abalado de novo, vira apavorado. Condição de medo.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Agarrado', $$Fica desprevenido e imóvel, sofre -1d20 em testes de ataque e só pode atacar com armas leves. Ataque à distância contra alvo agarrado tem 50% de chance de acertar o alvo errado. Condição de paralisia.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Alquebrado', $$Custo em PE de habilidades e rituais do personagem aumenta em +1. Condição mental.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Apavorado', $$Sofre -2d20 em testes de perícia e deve fugir da fonte do medo da forma mais eficiente possível (pode parar se perder a fonte de vista ou se afastar mais que alcance médio); se não puder fugir, pode agir mas não pode se aproximar voluntariamente da fonte do medo. Condição de medo.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Asfixiado', $$Não pode respirar; prende a respiração por rodadas = Vigor; depois disso, Fortitude por rodada (DT 5+5 por teste anterior) — falhar = cai inconsciente e perde 1d6 PV/rodada até respirar ou morrer.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Atordoado', $$Fica desprevenido e não pode fazer ações. Condição mental.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Caído', $$Sofre -2d20 em ataques corpo a corpo; deslocamento reduzido a 1,5m; –5 na Defesa contra ataques corpo a corpo, mas +5 na Defesa contra ataques à distância.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Cego', $$Fica desprevenido e lento; não pode fazer testes de Percepção pra observar; sofre -2d20 em testes de perícias baseadas em Agilidade ou Força; todos os alvos de seus ataques recebem camuflagem total; considerado cego em área de escuridão total, a menos que algo permita perceber no escuro. Condição de sentidos.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Confuso', $$Comporta-se de modo aleatório; rola 1d6 no início de cada turno: 1) move-se numa direção aleatória (1d8); 2-3) sem ações, balbucia incoerentemente; 4-5) ataca o ser mais próximo com a arma empunhada (ou a si mesmo se estiver sozinho, só rolando o dano); 6) a condição termina e age normalmente. Condição mental.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Debilitado', $$Sofre -2d20 em testes de Agilidade, Força e Vigor. Se ficar debilitado de novo, vira inconsciente.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Desprevenido', $$Despreparado pra reagir; sofre –5 na Defesa e -1d20 Reflexos. Fica desprevenido contra inimigos que não possa perceber.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Doente', $$Sob efeito de uma doença.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Em Chamas', $$Pegando fogo; sofre 1d6 dano de fogo no início de cada turno; ação padrão apaga o fogo com as mãos; imersão em água também apaga.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Enjoado', $$Só pode realizar uma ação padrão OU de movimento (não ambas) por rodada.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Enlouquecendo', $$Se iniciar 3 turnos enlouquecendo na mesma cena (não necessariamente consecutivos), fica insano — o personagem se torna um NPC. Pode ser encerrada com teste de Diplomacia (DT 20+5 por vez que já tiver sido acalmado na cena) ou por qualquer efeito que cure ao menos 1 de Sanidade.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Enredado', $$Fica lento e vulnerável, sofre -1d20 em testes de ataque. Condição de paralisia.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Envenenado', $$Varia conforme o veneno; pode ser outra condição (ex.: fraco ou enjoado) ou dano recorrente (ex.: 1d12/rodada); a descrição do veneno determina a duração (padrão: dura a cena); dano recorrente de envenenado sempre se acumula, mesmo se as condições/fontes forem iguais.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Esmorecido', $$Sofre -2d20 em testes de Intelecto e Presença. Condição mental.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Exausto', $$Fica debilitado, lento e vulnerável. Se ficar exausto de novo, vira inconsciente. Condição de fadiga.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Fascinado', $$Atenção presa em algo; sofre -2d20 em Percepção e não pode agir, exceto observar o que o fascinou; qualquer ação hostil contra o personagem anula a condição; balançar um ser fascinado pra tirá-lo desse estado gasta ação padrão. Condição mental.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Fatigado', $$Fica fraco e vulnerável. Se ficar fatigado de novo, vira exausto. Condição de fadiga.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Fraco', $$Sofre -1d20 em testes de Agilidade, Força e Vigor. Se ficar fraco de novo, vira debilitado.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Frustrado', $$Sofre -1d20 em testes de Intelecto e Presença. Se ficar frustrado de novo, vira esmorecido. Condição mental.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Imóvel', $$Todas as formas de deslocamento reduzidas a 0m. Condição de paralisia.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Inconsciente', $$Fica indefeso e não pode fazer ações, incluindo reações. Balançar um ser pra acordá-lo gasta ação padrão.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Indefeso', $$Considerado desprevenido, mas sofre –10 na Defesa, falha automaticamente em testes de Reflexos e pode sofrer golpes de misericórdia.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Lento', $$Todas as formas de deslocamento reduzidas à metade (arredonda pra baixo pro primeiro incremento de 1,5m); não pode correr ou fazer investidas. Condição de paralisia.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Machucado', $$O personagem tem metade ou menos de seus pontos de vida totais.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Morrendo', $$Com 0 pontos de vida. Se iniciar 3 turnos morrendo na mesma cena (não necessariamente consecutivos), morre. Pode ser encerrada com teste de Medicina (DT 20+5 por vez que já tiver sido estabilizado na cena) ou por efeitos específicos.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Ofuscado', $$Sofre -1d20 em testes de ataque e de Percepção. Condição de sentidos.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Paralisado', $$Fica imóvel e indefeso, só pode realizar ações puramente mentais. Condição de paralisia.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Pasmo', $$Não pode fazer ações. Condição mental.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Perturbado', $$Na primeira vez que isso acontece numa cena, recebe um efeito de insanidade.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Petrificado', $$Fica inconsciente e recebe resistência a dano 10.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Sangrando', $$Ferimento aberto; no início de cada turno, teste de Vigor (DT 20) — passando, estabiliza e remove a condição; falhando, perde 1d6 PV e continua sangrando. Também é possível estabilizar alguém com ação completa + teste de Medicina (DT 20).$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Surdo', $$Não pode fazer testes de Percepção pra ouvir; sofre -2d20 em testes de Iniciativa; considerado em condição ruim pra lançar rituais. Condição de sentidos.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Surpreendido', $$Não ciente de seus inimigos; fica desprevenido e não pode fazer ações.$$),
((select id from sources where slug='ordem_paranormal'), 'condicao', 'Vulnerável', $$Sofre –2 na Defesa.$$),

((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Abocanhar', $$Leva até 2 agarrados pra dentro da boca central; ao ser abocanhado, e no início de cada turno da aberração enquanto continuar agarrado, sofre 3d6 dano de perfuração (Fortitude DT 15 reduz à metade); qualquer personagem adjacente pode gastar ação padrão + Atletismo DT 20 pra tentar tirar alguém de dentro da boca. (Aberração de Carne)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Aceleração', $$Quem sofre dano da pancada entra em "aceleração" — no próximo turno, se fizer movimento+padrão ou ação completa, sofre 4d12 dano de Energia adicional. (Anárquico Descontrolado)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Acorrentar', $$Ao acertar correntes num alvo Médio ou menor, tenta agarrar à distância (Teste +17, 2d20); estrangula agarrados no início do turno por 4d6 dano de impacto; até 2 agarrados por vez. (Enpap-X)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Afogamento', $$Quem sofre esse dano fica asfixiado (Fortitude DT 35 evita; repetível no fim de cada turno). (Anfitrião)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Afogar em Sangue', $$Invade nariz/boca de um alvo em alcance curto, afogando-o em Sangue; fica asfixiado; no início de cada turno, Fortitude DT 24 encerra a condição e expele a mulher afogada líquida pra um espaço adjacente. (Mulher Afogada)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Agarrada Mumificadora', $$Ao acertar garra enfaixada, tenta agarrar (Teste +30, 4d20); agarrado sofre 4d8+30 dano de Morte no início de cada turno, e a múmia recupera o mesmo tanto de PV; se reduzido a 0 PV assim, vira esqueleto de Lodo no início do seu turno. (Múmia Xipófaga)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Agarrar e Estrangular', $$Ao acertar pancada num alvo Médio ou menor, tenta agarrar (Teste +35, 5d20); agarrado também fica asfixiado; até 2 agarrados por vez. (Degolificada)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Agarrão (variações por criatura)', $$Aberração de Carne: se acertar um ataque de pancada, tenta agarrar o alvo (Teste +12, 3d20); mantém até 2 personagens agarrados por vez.
Aniquilação: ao acertar tentáculos espinhentos, tenta agarrar (Teste +50, 5d20); até 4 agarrados por vez.
O Deus da Morte: ao acertar soco espiral em alvo Médio ou menor, tenta agarrar (Teste +47, 6d20).
Sukkalgir: ao acertar mordida num alvo Médio ou menor, tenta agarrar (Teste +15, 3d20).
Viajante: ao acertar pancada num alvo Médio ou menor, tenta agarrar (Teste +15, 2d20).$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Apagar Memória', $$Um alvo que enlouqueça pelo Estrangeiro fica com a mente controlada por ele; alternativamente, pode apagar a memória da vítima e devolver 1d4 de Sanidade, fazendo-a duvidar do encontro. (Estrangeiro)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Apertar e Destruir', $$No início do turno, aperta os agarrados: 40 de dano de Sangue. (Aniquilação)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Arrancar Sangue', $$Ao ser arrancada de um corpo que está afogando, carrega parte do sangue: 6d6 dano de Sangue + deixa fraco. (Mulher Afogada)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Arremessar (Flor Rosa)', $$Ergue um alvo em alcance curto e o arremessa a um ponto também em alcance curto; 2d6 dano de impacto + caído (Reflexos DT 15 evita tudo); a flor murcha com fertilizante (perde a habilidade, -1d20 em Luta). (Dama de Sangue)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Aterrorizar', $$Fica parado, olhar profundo entra na alma do alvo; se adjacente, sofre 4d10+10 dano mental. (Ocioso)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Atormentar (variações por criatura)', $$Bicho-Papão: sussurros num alvo em alcance curto: 3d8 dano mental (Vontade DT 30 reduz à metade); +3d8 se estiver escondido do alvo.
Parasita de Culpa: fixado, todos no sonho sofrem 2d6 dano mental no início de cada cena do sonho (Vontade DT 20 reduz à metade).$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Atropelar', $$Percorre até o dobro do deslocamento, passando pelo espaço de outros seres; ataca de pancada infectada cada ser nos espaços por onde passa. (Infecticídio)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Autodestruição', $$Concentra Energia e se autodestrói: 8d12 dano de Energia em todos em alcance curto (Reflexos DT 25 reduz à metade; adjacentes -2d20 no teste); o anárquico descontrolado morre ao usar. (Anárquico Descontrolado)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Bater as Asas', $$Todos em alcance longo sofrem 8d6 dano Mental, são empurrados 6m e ficam atordoados 1 rodada (Fortitude DT 40 reduz à metade e evita efeitos). (Aniquilação)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Brilho Enlouquecedor', $$1x/rodada, marcas douradas brilham; todos em alcance médio que o veem sofrem 1d6 dano mental (Vontade DT 14 reduz à metade). (Existido)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Chamas Reveladoras', $$Círculo de chamas douradas se expande em alcance médio; todos na área sofrem 10d8 dano de Conhecimento (Vontade DT 43 reduz à metade); quem sofre ganha uma "auréola reveladora" — até o fim da cena o anjo sabe onde estão todos com auréola, ignorando furtividade/invisibilidade/ilusão. (Anjo)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Chuva de Ácido (Flor Vermelha)', $$Todos em alcance curto sofrem 4d4 dano químico (Fortitude DT 15 reduz à metade); murcha com agrotóxico (perde a habilidade, -5 resistências a dano). (Dama de Sangue)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Cinzas das Terras Desoladas', $$Área de alcance longo ao redor vira terreno acelerado pelo tempo (tudo vira pó); cada ser na área sofre 10d10+20 dano de Morte + enjoado (Fortitude DT 43 reduz à metade e evita a condição); terminar o turno na área causa mais 20 de dano de Morte. (Ceifador Espiral)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Comandar', $$Ao causar dano com rajada psíquica, tenta dominar a mente (Vontade DT 35 evita, Intelecto 5+ é imune); obedece uma ordem no próximo turno — Atacar (ataca um aliado sem gastar PE), Render-se (cai e arremessa armas numa direção aleatória em alcance curto), ou Fugir (se afasta da forma mais eficiente). (Estrangeiro)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Comando', $$Comanda um alvo em alcance curto a agir da forma mais eficiente possível (Vontade DT 29 evita) — replica um efeito básico do ritual Perturbação. (Carniçal Preto da Morte)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Comportamento Errático', $$No início do turno, rola 1d6 três vezes e executa em ordem (ação não realizável = fica parado, perde essa ação e ganha +10 resistência a dano até o próximo turno, por ação perdida): 1-2 salta até 18m até o mais próximo, agride com garras se adjacente. 3 vira facho de Energia até ficar adjacente a um alvo aleatório entre os que o enfrentam. 4 parte do corpo explode: 4d12+20 (alcance médio) / 6d12+20 (curto) / 8d12+20 (adjacente) dano de Energia (Reflexos DT 30 reduz à metade em médio/curto); perde 50 PV ao usar. 5 risada descontrolada: fica desprevenido até o próximo turno, mas ataques ficam imprevisíveis (sem esquiva possível). 6 toca um adjacente: 10d12+20 dano de Energia (Fortitude DT 30 reduz à metade). (Anomiático)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Contemplar a Espiral', $$Todos em alcance médio que o veem sofrem 10d10+30 dano mental (Vontade DT 43 reduz à metade); quem sofre fica imune até o fim da cena. (Ceifador Espiral)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Correntes de Lodo', $$Projeta vinhas de Lodo em toda área de alcance médio; todos na área sofrem 20d6 dano de Morte (Fortitude DT 40 reduz à metade); quem fica machucado é infectado (vulnerabilidade a Morte até o fim da cena); quem chega a 0 PV vira um enraizado. (Sempiternal)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Cravar Chifres', $$Investida com chifres que acerta crava e agarra o alvo (não pode atacar com chifres enquanto mantém); no fim de cada turno da vítima ainda agarrada, sofre 4d12+20 dano de Sangue. (Minotauro)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Crescer', $$A cada socão que acerta, +1d6 cumulativo de dano nas próximas rolagens até o fim do turno (1º acerto → +1d6 no 2º ataque, 2º acerto → +2d6 no 3º, etc.). (Enpap-X)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Cópia Observada', $$Manifesta uma cópia de alguém deixado enlouquecendo por Espreitar — usa a mesma ficha, mas causa dano de Conhecimento em vez do normal, não conjura rituais/habilidades paranormais, dura até o fim da cena. (Espreitador)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Cópias do Hospedeiro', $$Fixado, manifesta uma cópia de Conhecimento do hospedeiro (mesmas estatísticas, mas 20 PV e dano de Conhecimento); até 4 cópias por vez; dentro do sonho usa a Presença do parasita no lugar dos próprios atributos. (Parasita de Culpa)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Derrubar e Devorar', $$Manobra de derrubar em alvo a até 3m (Teste +45, 5d20); vencendo, desfere 3 mordidas (dano sobe pra 4d12+40). (Kerberos)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Desejos de Sangue', $$Todos em alcance médio entram em fúria e atacam outro personagem em alcance curto à escolha do Diabo (Vontade DT 45 evita); afetados usam a ação de maior potencial de dano, sem conjurar rituais; quem passa fica imune até o fim da cena. (O Diabo)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Desespero', $$Quem sofre dano do toque da dor sofre o mesmo tanto de dano mental (Vontade DT 25 reduz o dano mental à metade). (Rastejador Sombrio)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Desfiguramento Capilar', $$Usa os cabelos pra penetrar orifícios faciais de agarrados; sofrem 10d6+20 dano de perfuração (Fortitude DT 35 reduz à metade) e 6d10 dano mental (Vontade DT 35 reduz à metade). (Degolificada)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Desovar Aranhas', $$1x/cena, ao ficar machucada, desova aranhas menores; efeitos progressivos por turno — T1: quem começa turno em alcance curto sofre 2d6 dano mental (Vontade DT 15 reduz à metade); T2+: também 2d8 dano de Morte (Fortitude DT 15 reduz à metade); T3+: os efeitos passam a alcançar alcance médio; T4+: se alguém morrer em alcance médio, é consumido e vira uma nova aracnasita com 70 PV, sem esta habilidade. (Aracnasita)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Devorar', $$1x/cena, ao reduzir alguém a 0 PV com a mordida, devora e mata instantaneamente, recuperando metade dos PV totais da vítima (Fortitude DT 40 evita). (Kerberos)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Devorar Memória', $$Entra na mente de um agarrado e devora memórias: 4d12 dano mental + esquece completamente uma pessoa (Vontade DT 29 reduz à metade e evita); cada vítima perturbada assim aumenta o dano da pancada em +1d12 até o fim da cena. (Viajante)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Disparar Teia', $$Teia em área de 3m em alcance curto; quem está ou entra fica agarrado (Reflexos DT 20 evita); tomada pelo Lodo, causa 2d8+10 dano de Morte no início do turno de quem está agarrado; escapa causando 15 de dano de corte na teia ou ação padrão + Atletismo DT 20; dura até o fim da cena. (Aracnasita)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Espinhos (Flor Amarela)', $$Dispara em até 3 alvos em alcance médio, 2d8 dano de perfuração cada (Reflexos DT 15 reduz à metade); murcha com 10+ dano de fogo de um efeito (perde a habilidade, -1d20 em Reflexos). (Dama de Sangue)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Espiral de Lodo', $$Vira poça e se lança como espiral perfurante até 9m em linha reta; quem estiver no caminho sofre 2d10 dano de Morte (Reflexos DT 14 reduz à metade); se reforma no fim do trajeto. (Esqueleto de Lodo)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Espiral Descendente', $$Acelera o tempo de um agarrado, paralisado sem poder agir; envelhece 3d20 anos, 1 dano mental por ano envelhecido. (O Deus da Morte)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Espiral Destrutiva', $$Espiral de Morte de 12m de raio em alcance longo; todos na área sofrem 10d10+50 dano de Morte (Fortitude DT 45 reduz à metade). (O Deus da Morte)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Espreitar', $$1x/cena, adjacente a um ser dormindo, causa 10d6 dano mental (Vontade DT 30 reduz à metade); se a vítima enlouquecer com esse dano, pode criar uma Cópia Observada dela. (Espreitador)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Estacar', $$Ao causar dano com a mordida, usa Lodo pra prender o alvo: +1d10 dano de Morte + agarrado (solta com ação padrão + Atletismo DT 20, ou ajuda de adjacente). (Aracnasita)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Estrangulamento Final', $$Desloca 15m; quem fica adjacente durante o deslocamento fica agarrado e asfixiado (Reflexos DT 30 evita); escapar exige ação padrão + Reflexos DT 30. (Aniquilação)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Estraçalhar', $$Ao acertar mordida, causa 4d12+10 dano de perfuração + sangrando até o fim da cena (Reflexos DT 30 reduz o dano à metade e evita a condição). (Titã de Sangue)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Expandir Aura', $$Quem está em alcance curto sofre 6d6 dano mental (Vontade DT 20 reduz à metade). (Lembrado)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Expandir em Radiação', $$Todos em alcance longo sofrem 10d20+20 dano de Energia (Reflexos DT 40 reduz à metade); o próprio tempestuoso perde 100 PV ao usar. (Tempestuoso)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Explodir em Sangue', $$Ao causar dano com arma sangrenta ou tocar diretamente numa ferida, 10d6 dano de Sangue; até 2x/turno. (O Diabo)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Faixas Detentoras', $$Ao acertar asas num alvo Médio ou menor, tenta agarrar (Teste +45, 5d20); agarrado fica fascinado; mantém 1 agarrado por vez, sem impedir o uso das asas. (Anjo)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Fixar', $$Aproxima-se de alguém dormindo; Percepção do alvo (-2d20 por dormir) vs. Furtividade do parasita (+15, 2d20) — se o alvo passar, acorda antes da fixação e o parasita foge; se falhar, vira hospedeiro (ver Devorar Culpa). (Parasita de Culpa)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Forma Desencadeada', $$Crítico com socão ou corrente pode derrubar o alvo ou empurrá-lo 3m. (Enpap-X)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Fortalecimento Paranormal', $$Até o fim da cena, +1d20 em testes de Agilidade/Força/Vigor e +2d4 dano de Conhecimento nas pancadas; só usável se já causou dano mental com Brilho Enlouquecedor nesta cena. (Existido)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Grito de Desespero', $$Todos em alcance médio sofrem 3d12 dano mental (Vontade DT 20 reduz à metade; cobertura dá +5 no teste). (Sukkalgir)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Grito Devastador (Flor Roxa)', $$Todos em alcance curto ficam confusos (Vontade DT 15 evita, repetível no fim do turno); murcha com bulbo de bravo purpulis (perde a habilidade, -1d20 em Vontade). (Dama de Sangue)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Grito Rasgado', $$1x/cena, rompe a vedação da boca; todos em alcance médio sofrem 4d10+10 dano mental + efeito aleatório (1d4: 1 surdo permanente dos dois ouvidos; 2 surdo permanente de um; 3 surdo dos dois até o fim da cena; 4 surdo de um até o fim da cena) — Vontade DT 35 reduz o dano à metade e evita o efeito. (Degolificada)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Hipnose', $$Domina a mente de um alvo em alcance curto (Vontade DT 29 evita); controle telepático total exceto suicídio; repete o teste no fim de cada turno (+1 cumulativo por tentativa); até 3 hipnotizados por vez; se usado num alvo que enlouqueça, falha automática e domínio permanente (até o carniçal ser destruído — nesse caso pode até ser comandado a se matar). (Carniçal Preto da Morte)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Implantar Confusão', $$1x/rodada, tenta agarrar quem acabou de sofrer dano do toque (Teste +10, 4d20); conseguindo, implanta imagens traumáticas: 2d8 dano mental (Vontade DT 15 reduz à metade) + vulnerabilidade a Energia até o fim da cena. (Perturbado de Energia)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Incubar', $$Toca um adjacente alheio à sua presença (sob Oblívio) e implanta uma larva; enquanto incuba, o Estrangeiro tem acesso total à mente do hospedeiro; a larva causa 1d6 dano mental no início de cada cena; Sanidade 0 faz um novo Estrangeiro eclodir da cabeça, matando o hospedeiro instantaneamente. (Estrangeiro)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Infecção', $$Quem sofre dano das pancadas é infectado pelo vírus (Fortitude DT 30 evita; passar dá imunidade até o fim da cena). (Infecticídio)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Instinto Aniquilador', $$Qualquer um em alcance curto que se mova mais de 3m sofre um ataque de tentáculos espinhentos. (Aniquilação)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Invadir Órgãos', $$Invade órgãos vitais de quem está afogando; 6d6 dano de Sangue + enjoado. (Mulher Afogada)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Ironia do Destino', $$2 ataques de foice num adjacente; se acertar o 2º, agarra a vítima e pode se deslocar 6m carregando-a; enquanto agarra, divide o dano que sofre com a vítima. (Marionete)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Manipular Ondas da Existência', $$No fim do turno, ativa/desativa/opera até 6 objetos tecnológicos em alcance médio, ou sobrecarrega-os causando 2d12 dano de Energia por objeto em todos na área (Reflexos DT 30 reduz à metade). (Anomalia)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Marcas do Terror', $$Todos em alcance curto sofrem 4d6 dano mental (Vontade DT 25 reduz à metade); quem passa fica imune até o fim da cena. (Enpap-X)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Miasma Fétido (Flor Azul)', $$Todos em alcance curto ficam enjoados 1d4+1 rodadas (Fortitude DT 15 reduz pra 1 rodada); murcha com dano de eletricidade/Energia (perde a habilidade, -6m deslocamento). (Dama de Sangue)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Oblívio', $$Quem sofre dano do Toque Sutil esquece a existência do Estrangeiro (Vontade DT 30 evita); considera-o invisível; repete o teste no fim de cada turno (passar encerra o efeito mas causa 6d6 dano mental); vítima incubando uma larva não repete o teste. (Estrangeiro)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Pacto', $$Oferece um pacto de Sangue; se aceito, cumpre o prometido (com resoluções distorcidas); o alvo sofre 10d6 dano mental e, se enlouquecer, vira servo obcecado pelo Diabo pra sempre. (O Diabo)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Pancada Poderosa', $$Crítico com a garra empurra o alvo 6m; colisão com objeto resistente ou outro ser causa 4d6 dano de impacto (a ambos, se for um ser). (Carniçal Preto da Morte)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Permanecer Próximo', $$1x/rodada, teleporta pra qualquer ponto dentro do campo de visão do alvo. (Ocioso)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Plantar Paranoia', $$Chacoalha a Membrana; todos em alcance médio ficam abalados (Vontade DT 15 evita; já abalado vira apavorado); -1d20 no teste se o vulto estiver escondido ao usar. (Vulto)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Prender na Tela', $$Desintegra um alvo em alcance curto e o materializa dentro da tela (Fortitude DT 30 evita); preso fica paralisado, 2d12 dano mental no início de cada turno; sempre que o telopsia sofrer 50+ dano num turno, o preso pode repetir Fortitude pra escapar e se materializar adjacente. (Telopsia)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Prisão de Tentáculos (Flor Verde)', $$Penetra o solo e agarra um alvo em alcance curto até os tentáculos serem destruídos (20 PV, acertados automaticamente); murcha em água corrente (perde a habilidade, -5 Defesa). (Dama de Sangue)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Queimar (Aeneas)', $$Cone de chamas em alcance médio; todos na área sofrem 10d6+20 dano de Energia (Reflexos DT 45 reduz à metade). (Anfitrião)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Raio de Energia Radioativa', $$Ao acertar 2 garras no mesmo alvo, projeta um raio dele até outro alvo em alcance médio: 4d20+20 dano de Energia (Reflexos DT 40 reduz à metade). (Tempestuoso)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Raio Dourado', $$1x/cena, linha de 3m em alcance longo; todos na linha sofrem 15d8+50 dano de Conhecimento (Reflexos DT 43 reduz à metade). (Anjo)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Rasteira de Tentáculo', $$1x/rodada, ao ficar adjacente a 2+ seres, ataca um com tentáculo; se acertar, alvo cai e é empurrado 6m. (Carente)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Rastejar', $$Até o início do próximo turno, sob cobertura/camuflagem, +10 em Furtividade e desloca furtivamente sem penalidade. (Rastejador Sombrio)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Rastrear e Abater', $$+6d6 dano contra alvos desprevenidos. (Nidere)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Reescrever Realidade', $$Altera propriedades de seres/objetos em alcance médio. Contra objetos (até 1 tonelada): muda composição/posição/estado da matéria (objetos vestidos/empunhados: Reflexos DT 45 do portador evita). Contra seres: 10d6 dano de Conhecimento + 10d6 dano mental + uma condição qualquer (exceto morrendo/enlouquecendo) — Vontade DT 45 reduz cada dano à metade e evita a condição. (Máscara do Desespero)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Reflexos Guiados por Corda', $$1x/rodada, quando alguém fica adjacente, ataca com a foice. (Marionete)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Retaliação', $$Ao ser atacado ou alvo de habilidade, teleporta pra adjacente ao atacante e ataca corpo a corpo (Teste +30, 5d20 · Dano 4d10+20 impacto não letal). (Ocioso)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Reverter', $$Quem sofre dano das garras invertidas fica enjoado até o fim do próximo turno (surto temporal apodrece a carne). (Nidere)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Romance Forçado', $$Ao acertar, escolhe outro ser visível; os dois decidem entre si quem sofre o dano. (Anfitrião)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Romper Consciência', $$No início do turno, sorteia um alvo em sua linha de visão: 10d6 dano mental (Vontade DT 41 reduz à metade); se enlouquecer com isso, é absorvido pela anomalia. (Anomalia)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Saltar e Assustar', $$Se escondido de um alvo em alcance curto, sai do esconderijo assumindo forma assustadora; alvo sofre 10d8 dano mental (Vontade DT 35 reduz à metade). (Bicho-Papão)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Sangrar', $$Ao acertar com o chifre, pode soltá-lo preso no alvo (vulnerabilidade a Sangue até remover — ação padrão + 8d8 dano de Sangue pra remover); o chifre sempre recresce no início do turno do Diabo. (O Diabo)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Sucção', $$Ao acertar mordida, prende os dentes no rosto e suga o ar; Fortitude DT 17 solta; falhar deixa inconsciente e, no início do próximo turno do succ, reduz a 0 PV e morrendo; enquanto prende, o succ só pode usar reações e seu deslocamento cai pra 3m; sofrer 10+ dano numa rodada faz o succ soltar qualquer vítima. (Succ)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Sugada Mortal', $$Com o ferrão, sugar fluidos apodrece órgãos; atingido fica debilitado e enjoado até o fim da cena (Fortitude DT 35 evita). (Carente)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Teatro (Amphitruo)', $$Envia texto incompreensível à mente do alvo, que deve decorar e recitar em segundos ou sofre 10d6 dano mental (Artes DT 35 ou Vontade DT 45 evita). (Anfitrião)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Tela Zumbificadora', $$Projeta imagens enlouquecedoras; todos em alcance médio sofrem 6d6 dano mental + confusos até o fim da cena (Vontade DT 30 reduz o dano à metade e evita a condição); quem já está confuso e falha fica também fascinado. (Telopsia)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Tempestade de Espinhos', $$Todos em alcance médio sofrem 20d6+20 Sangue (Reflexos DT 40 reduz à metade); 1x/cena, e perde Disparo de Espinhos pelo resto da cena ao usar. (Aniquilação)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Tentáculos das Sombras', $$Projeta fibras pelas sombras em até 3 alvos em alcance médio, agarrando-os (Reflexos DT 28 evita); pode arrastar os agarrados até outro ponto em alcance médio com ação de movimento; agarrados sofrem 4d6 dano mental no fim de cada turno. (Rastejador Sombrio)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Toque Devastador', $$Toca até 2 seres/objetos, causando o dano da Aura Tangível. (Silhueta)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Visão Macabra (Flor Laranja)', $$Todos em alcance médio sofrem 1d6 dano Mental (Vontade DT 15 reduz à metade); murcha com 10+ dano de corte de um efeito (perde a habilidade, -20 PV totais). (Dama de Sangue)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Você é Minha Mamãe?', $$Usa a forma infantil pra abraçar um adjacente, que fica paralisado até ser solto (Reflexos DT 25 evita); mantém indefinidamente, mas solta se sofrer dano de Energia. (Carente)$$),
((select id from sources where slug='ordem_paranormal'), 'efeito_inimigo', 'Vomitar Lodo', $$1x/cena, na primeira rodada após ser manifestada, cada cópia despeja Lodo num alvo em alcance curto: 4d10+10 dano de Morte + lento até o fim da cena (Reflexos DT 25 reduz à metade e evita). (Escutado)$$),

((select id from sources where slug='ordem_paranormal'), 'habilidade', 'Aura Desesperada', $$Quem começa o turno em alcance curto sofre 2d12 dano mental (Vontade DT 25 reduz à metade). (Sukkalgir)$$),
((select id from sources where slug='ordem_paranormal'), 'habilidade', 'Aura Radioativa', $$Quem começa turno em alcance curto sofre 2d20+20 dano de Energia (Fortitude DT 40 reduz à metade). (Tempestuoso)$$),
((select id from sources where slug='ordem_paranormal'), 'habilidade', 'Aura Tangível', $$Quem toca nela sofre 20d12 dano de Conhecimento (Fortitude DT 42 reduz à metade; 0 PV = desintegração instantânea; só 1x/turno por ser/item). (Silhueta)$$),
((select id from sources where slug='ordem_paranormal'), 'habilidade', 'Veneno Pútrido', $$Primeiro dano do punho espinhento numa cena envenena; no início de cada turno, Fortitude DT 23 ou 4d12 dano de Morte (passar cura o veneno). (Enraizado)$$),

((select id from sources where slug='ordem_paranormal'), 'extra', 'Acólito', $$Pessoa envolvida com o paranormal, conhecimento suficiente pra auxiliar em rituais. Bônus: +1d20 em Ocultismo, não precisa manipular componentes ritualísticos. Conjuração Conjunta: 1 PE ao conjurar ritual pra +2 na DT contra esse ritual.$$),
((select id from sources where slug='ordem_paranormal'), 'extra', 'Cavalo', $$Montaria: aumenta deslocamento pra 15 e dá ação extra por rodada (só deslocamento), se treinado em Adestramento.$$),
((select id from sources where slug='ordem_paranormal'), 'extra', 'Cão Adestrado', $$Cão treinado pra investigação e combate. Bônus: +2 Investigação/Percepção. Ladrar e Morder: 1 PE pra +2 Defesa por 1 rodada.$$),
((select id from sources where slug='ordem_paranormal'), 'extra', 'Faz-tudo', $$Pessoa treinada em perícias. Bônus: treina 2 perícias à escolha (exceto Luta/Pontaria). Dica Valiosa: 1 PE pra +1d6 num teste dessas perícias.$$),
((select id from sources where slug='ordem_paranormal'), 'extra', 'Guerrilheiro', $$Treinado em combate armado. Bônus: +1d20 em ataque. Ataque Conjunto: 1 PE ao acertar pra +1d8 dano.$$),
((select id from sources where slug='ordem_paranormal'), 'extra', 'Socorrista', $$Treinado em primeiros socorros. Bônus: treinado em Medicina. Bolsa de Remédios: 1 PE pra recuperar 1d8+1 PV (si mesmo ou aliado adjacente).$$);
